#!/usr/bin/env python3
"""Upgrade only the existing isolated X component; never copies account/session secrets."""
import base64,datetime as dt,fcntl,hashlib,json,os,pathlib,shutil,subprocess,sys
APP=pathlib.Path('/opt/umraniye-osint-x-twscrape-deneme')
STATE=pathlib.Path('/var/lib/umraniye-osint-x-twscrape-deneme')
SERVICE='umraniye-osint-x-twscrape-deneme.service'
EXPECTED='36ad7af3148d354e59536ac0aae86ae51f03153b28b4cb6f6153d9ee4d41fd5b'
PAYLOAD={'worker.py': '', 'coverage.py': '', 'test_coverage.py': '', 'coverage_fixtures.py': '', 'config.example.json': 'ew0KICAic2hhZG93IjogdHJ1ZSwNCiAgInRlbGVncmFtIjogZmFsc2UsDQogICJwcm9kdWN0aW9uV3JpdGVzIjogZmFsc2UsDQogICJxdWVyaWVzUGVyUm91bmQiOiA2LA0KICAicmVzdWx0c1BlclF1ZXJ5IjogNDAsDQogICJ0aW1lb3V0U2Vjb25kcyI6IDEyMCwNCiAgImZyZXNobmVzc01pbnV0ZXMiOiA2MA0KfQ==', 'README.md': ''}

def command(args,timeout=30):
 return subprocess.run(args,capture_output=True,text=True,timeout=timeout)

def main():
 if os.geteuid()!=0:raise RuntimeError('sudo_required')
 if APP.is_symlink() or STATE.is_symlink():raise RuntimeError('symlink_target_denied')
 if hashlib.sha256((APP/'worker.py').read_bytes()).hexdigest()!=EXPECTED:raise RuntimeError('source_version_changed_no_install')
 active=command(['systemctl','show',SERVICE,'--property=ActiveState','--value']).stdout.strip()
 if active in ('active','activating','reloading'):raise RuntimeError('shadow_round_running_no_changes')
 backup=pathlib.Path('/var/lib/umraniye-osint-deneme/backups')/('x-coverage-v2-'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
 backup.mkdir(mode=0o700,parents=True)
 old={};created=[]
 for name in PAYLOAD:
  target=APP/name
  if target.is_symlink():raise RuntimeError('symlink_file_denied')
  old[name]=target.read_bytes() if target.exists() else None
  if old[name] is not None:(backup/name).write_bytes(old[name])
 rollback=['#!/usr/bin/env python3','from pathlib import Path','import shutil','app=Path('+repr(str(APP))+')','backup=Path(__file__).resolve().parent']
 for name,data in old.items():
  rollback.append("shutil.copyfile(backup/"+repr(name)+",app/"+repr(name)+")" if data is not None else "(app/"+repr(name)+").unlink(missing_ok=True)")
 (backup/'geri-al.py').write_text('\n'.join(rollback)+'\n')
 lock=open(STATE/'round.lock','a+b');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 try:
  for name,value in PAYLOAD.items():
   target=APP/name;temp=APP/(name+'.upgrade-tmp');temp.write_bytes(base64.b64decode(value));temp.chmod(0o644);temp.replace(target)
  test=command([str(APP/'venv/bin/python'),str(APP/'test_coverage.py')],90)
  if test.returncode:raise RuntimeError('offline_validation_failed')
 except Exception:
  for name,data in old.items():
   if data is None:(APP/name).unlink(missing_ok=True)
   else:(APP/name).write_bytes(data);(APP/name).chmod(0o644)
  raise
 finally:lock.close()
 result={'result':'x_coverage_v2_installed','maximumAccountCoveragePerRound':16,'maximumSearchQueriesPerRound':7,'maximumResultsPerQuery':40,'collectionBudgetSeconds':120,'perQueryCheckpoint':True,'rawCandidateRetentionHours':72,'freshAdmissionMinutes':60,'firstDiscoveryPreserved':True,'offlineTestsPassed':8,'newBrowserProcesses':0,'newTimers':0,'existingSiteRestarted':False,'telegramChanged':False,'mainDatabaseChanged':False,'backupPromoted':False,'backup':str(backup),'rollback':'sudo python3 '+str(backup/'geri-al.py')}
 if (STATE/'accounts.sqlite').exists():
  attempt=command(['systemctl','start',SERVICE],200)
  if (STATE/'report.json').exists():
   r=json.loads((STATE/'report.json').read_text())
   result['liveRound']={k:r.get(k) for k in ['at','status','liveAttempted','uniqueRead','accepted','newShadowRows','liveCollectionVerified','backupPromotionReady','promotionBlocker','retryAt']}
  result['serviceStartExit']=attempt.returncode
 else:result['liveRound']={'status':'session_missing','liveAttempted':False}
 (STATE/'coverage-v2-install-report.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
 print(json.dumps(result,ensure_ascii=False,indent=2))

if __name__=='__main__':
 try:main()
 except Exception as exc:print('KURULAMADI: '+(str(exc) if isinstance(exc,RuntimeError) else type(exc).__name__));sys.exit(1)
